function scanLocalRepository(path) {
  try {
    const fs = require('fs');
    const files = fs.readdirSync(path || '.', { withFileTypes: true });
    return JSON.stringify(files.map(f => ({ name: f.name, isDirectory: f.isDirectory() })));
  } catch (e) {
    return JSON.stringify({ error: e.message });
  }
}

